  font-size: var(--ck-font-size-tiny, var(--ck-font-size-xs));
  color: var(--ck-annotation-info-icon-color);
  grid-column: 1;
  align-self: center;
  margin-inline-end: var(--ck-spacing-padding-compact);
}

.ck .ck-annotation__info-name {
  font-weight: 500;
  font-size: var(--ck-font-size-control);
  color: var(--ck-color-annotation-info, var(--ck-annotation-info-name-color));
  grid-column: 1 / -1;
}

.ck .ck-annotation__info-time {
  color: var(--ck-color-annotation-info, var(--ck-annotation-info-time-color));
  grid-column: 2;
}

.ck.ck-balloon-panel .ck-annotation-wrapper .ck-annotation__info-name, .ck.ck-balloon-panel .ck-annotation-wrapper .ck-annotation__info-time {
  white-space: nowrap;
}

.ck .ck-annotation__actions {
  align-items: flex-start;
  gap: var(--ck-spacing-gap-snug);
  grid-area: actions;
  display: flex;

  & .ck.ck-dropdown {
    align-items: flex-start;
    display: flex;
  }
}

.ck .ck-annotation__content-wrapper {
  grid-area: content;
  width: 100%;

  &:not(:has(.ck-comment__input-wrapper)), & .ck-comment__input-wrapper .ck-comment__input {
    padding-inline-end: var(--ck-annotation-content-wrapper-padding-inline-end);
  }
}

@keyframes annotationFadeInLeft {
  from {
    opacity: 0;
    transform: translate3d(-5%, 0, 0);
  }

  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

:root, :host {
  --ck-annotation-wrapper-background-color: var(--ck-color-annotation-wrapper-background, #fff);
  --ck-annotation-wrapper-shadow: var(--ck-color-annotation-wrapper-drop-shadow, 0 1px 1px 1px #e6e6e6);
  --ck-annotation-wrapper-border-radius: var(--ck-border-radius-surface);
}

.ck.ck-sidebar {
  outline: 0;
  transition: min-height .25s;
  position: relative;

  @media (prefers-reduced-motion: reduce) {
    transition: none;
  }
}

.ck-sidebar-item {
  width: 100%;
  transition: top var(--ck-transition-duration-control-emphasized) ease, box-shadow var(--ck-transition-duration-control-emphasized) ease;
  position: absolute;

  @media (prefers-reduced-motion: reduce) {
    transition: none;
  }
}

.ck-sidebar-item--no-animation {
  transition: top !important;
}

.ck.ck-annotation-wrapper {
  border-radius: var(--ck-annotation-wrapper-border-radius);
  background: var(--ck-color-annotation-wrapper-background, var(--ck-annotation-wrapper-background-color));
  border: var(--ck-border-surface);
  outline: 0;
}

.ck.ck-annotation-wrapper--active, .ck.ck-annotation-wrapper:hover {
  & .ck-annotation__actions {
    opacity: 1;
  }
}

:root, :host {
  --ck-comments-archive-width: var(--ck-width-dialog);
  --ck-comments-archive-info-font-size: var(--ck-font-size-md);
}

.ck .ck-comments-archive-dropdown {
  &.ck-dropdown__panel {
    z-index: var(--ck-z-panel);
  }
}

.ck .ck-comments-archive {
  width: var(--ck-comments-archive-width);
  box-sizing: content-box;
  max-height: 450px;

  & .ck-annotation {
    animation: none;
  }

  & .ck-comments-archive__header, & .ck-comments-archive__content {
    max-height: 410px;
    padding: var(--ck-spacing-padding-comfortable);
    overflow: auto;
  }

  & .ck-comments-archive__header {
    max-height: 40px;
    line-height: var(--ck-font-size-normal, var(--ck-font-size-base));
    border-bottom: var(--ck-border-divider);
    font-weight: bold;
  }

  & .ck-comments-archive__content {
    & .ck-annotation-wrapper:not(:last-child) {
      margin-bottom: var(--ck-spacing-gap-comfortable);
    }
  }

  & .ck-comments-archive__info {
    text-align: center;
    font-style: italic;
    font-size: var(--ck-comments-archive-info-font-size);
    color: var(--ck-annotation-info-color);
  }
}

:root, :host {
  --ck-comment-marker-color: #fdecc3;
  --ck-comment-marker-active-color: #fbd988;
}

.ck-content .ck-comment-marker {
  background: var(--ck-color-comment-marker, var(--ck-comment-marker-color));
  border-top: 3px solid #0000;
  border-bottom: 3px solid #0000;

  &.ck-widget {
    border: 3px solid var(--ck-color-comment-marker, var(--ck-comment-marker-color));
    background-color: #0000;
  }
}

.ck-content .ck-comment-marker--active {
  background: var(--ck-color-comment-marker-active, var(--ck-comment-marker-active-color));

  & .ck-comment-marker {
    background: var(--ck-color-comment-marker-active, var(--ck-comment-marker-active-color));
  }

  &.ck-widget {
    border-color: var(--ck-color-comment-marker-active, var(--ck-comment-marker-active-color));

    & .ck-comment-marker {
      background-color: var(--ck-color-comment-marker, var(--ck-comment-marker-color));
    }
  }
}
